function findWords(board: string[][], words: string[]): string[] {
  const R = board.length, C = board[0].length;
  const onGrid = (w: string): boolean => {
    const dfs = (r: number, c: number, i: number): boolean => {
      if (r < 0 || c < 0 || r >= R || c >= C || board[r][c] !== w[i]) return false;
      if (i === w.length - 1) return true;
      const ch = board[r][c];
      board[r][c] = "#"; // used in this word
      const ok = dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1) || dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1);
      board[r][c] = ch;
      return ok;
    };
    for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) if (dfs(r, c, 0)) return true;
    return false;
  };
  return words.filter(onGrid);
}

