                    return False
                if i == len(w) - 1:
                    return True
                ch, board[r][c] = board[r][c], "#"  # used in this word
                ok = dfs(r + 1, c, i + 1) or dfs(r - 1, c, i + 1) or dfs(r, c + 1, i + 1) or dfs(r, c - 1, i + 1)
                board[r][c] = ch
                return ok

            return any(dfs(r, c, 0) for r in range(R) for c in range(C))

        return [w for w in words if on_grid(w)]

