class TrieNode {
  kids = new Map<string, TrieNode>();
  word: string | null = null; // set on the node where a word ends
}

function findWords(board: string[][], words: string[]): string[] {
  const root = new TrieNode();
  for (const w of words) {
    let node = root;
    for (const c of w) {
      if (!node.kids.has(c)) node.kids.set(c, new TrieNode());
      node = node.kids.get(c)!;
    }
    node.word = w;
  }
  const R = board.length, C = board[0].length, found: string[] = [];
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  const dfs = (r: number, c: number, parent: TrieNode): void => {
    const ch = board[r][c];
    const node = parent.kids.get(ch)!;
    if (node.word !== null) {
      found.push(node.word);
      node.word = null; // report each word once
    }
    board[r][c] = "#";
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < R && nc < C && node.kids.has(board[nr][nc])) dfs(nr, nc, node);
    }
    board[r][c] = ch;
    if (node.kids.size === 0 && node.word === null) parent.kids.delete(ch); // nothing left below: prune
  };

  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      if (root.kids.has(board[r][c])) dfs(r, c, root);
  return found;
}

